#include <Mahjong/Table/EmblemAtlas.h>
#include <gtest/gtest.h>

/**
 * The seat emblems: `assets/emblems/emblems.png` is generated by `tools/make_emblems.py` and read here from the source tree (a game's
 * content is not mounted in the test environment). The PNG is checked by its header (zlib is not linked into the tests; the pixels are
 * checked by `python3 tools/make_emblems.py --check`) against the numbers of `Table/EmblemAtlas.h`.
 */
namespace BECore::Mahjong::Tests {

    namespace {

        constexpr size_t kPngSignatureSize = 8;
        constexpr size_t kIhdrDataOffset = kPngSignatureSize + 8;  // after the signature, the chunk length and the chunk type
        constexpr size_t kIhdrSize = 13;
        constexpr size_t kIhdrTypeOffset = kPngSignatureSize + 4;  // the chunk type follows the 4 bytes of the chunk length
        constexpr size_t kIhdrHeightOffset = 4;                    // within the chunk data: width (4), height (4), depth, colour type, ...
        constexpr size_t kIhdrDepthOffset = 8;
        constexpr size_t kIhdrColorTypeOffset = 9;
        constexpr size_t kIhdrInterlaceOffset = 12;
        constexpr uint8_t kBitDepth = 8;
        constexpr uint8_t kColorTypeRgba = 6;
        constexpr uint8_t kNoInterlace = 0;
        constexpr unsigned char kPngSignature[kPngSignatureSize] = {0x89, 'P', 'N', 'G', '\r', '\n', 0x1A, '\n'};

        std::filesystem::path GameRoot() {
            return std::filesystem::path(__FILE__).parent_path().parent_path();
        }

        uint32_t ReadBigEndian(const std::vector<unsigned char>& bytes, size_t offset) {
            return (static_cast<uint32_t>(bytes[offset]) << 24) | (static_cast<uint32_t>(bytes[offset + 1]) << 16) | (static_cast<uint32_t>(bytes[offset + 2]) << 8) |
                   static_cast<uint32_t>(bytes[offset + 3]);
        }

        bool Overlap(const Rect& a, const Rect& b) {
            return a.x < b.x + b.w && b.x < a.x + a.w && a.y < b.y + b.h && b.y < a.y + a.h;
        }

        eastl::vector<int> DrawnCells() {
            eastl::vector<int> cells;
            cells.push_back(PersonCell());
            for (const ComputerLevel level : kAllLevels) {
                cells.push_back(ComputerCell(level));
            }
            cells.push_back(kTurnRingCell);
            cells.push_back(kCallingRingCell);
            return cells;
        }

    }  // namespace

    TEST(EmblemSpritesTest, ThePngIsAnRgbaPictureOfTheAtlasSize) {
        const std::filesystem::path pngPath = GameRoot() / kEmblemAtlasPath;
        std::ifstream file(pngPath, std::ios::binary);
        ASSERT_TRUE(file.is_open()) << pngPath.string();
        std::vector<unsigned char> head(kIhdrDataOffset + kIhdrSize);
        file.read(reinterpret_cast<char*>(head.data()), static_cast<std::streamsize>(head.size()));
        ASSERT_EQ(static_cast<size_t>(file.gcount()), head.size());
        EXPECT_TRUE(std::equal(std::begin(kPngSignature), std::end(kPngSignature), head.begin()));
        EXPECT_EQ(std::string(head.begin() + kIhdrTypeOffset, head.begin() + kIhdrDataOffset), "IHDR");
        EXPECT_EQ(ReadBigEndian(head, kIhdrDataOffset), static_cast<uint32_t>(kEmblemAtlasWidth));
        EXPECT_EQ(ReadBigEndian(head, kIhdrDataOffset + kIhdrHeightOffset), static_cast<uint32_t>(kEmblemAtlasHeight));
        EXPECT_EQ(head[kIhdrDataOffset + kIhdrDepthOffset], kBitDepth);
        EXPECT_EQ(head[kIhdrDataOffset + kIhdrColorTypeOffset], kColorTypeRgba);
        EXPECT_EQ(head[kIhdrDataOffset + kIhdrInterlaceOffset], kNoInterlace);
    }

    TEST(EmblemSpritesTest, EveryDrawnCellLiesInsideTheAtlasAndNoTwoOverlap) {
        const eastl::vector<int> cells = DrawnCells();
        ASSERT_EQ(cells.size(), static_cast<size_t>(kDrawnEmblemCells));
        for (size_t first = 0; first < cells.size(); ++first) {
            const Rect rect = EmblemRect(cells[first]);
            EXPECT_GE(rect.x, 0.0f) << cells[first];
            EXPECT_GE(rect.y, 0.0f) << cells[first];
            EXPECT_EQ(rect.w, static_cast<float>(kEmblemCellSize));
            EXPECT_EQ(rect.h, static_cast<float>(kEmblemCellSize));
            EXPECT_LE(rect.x + rect.w, static_cast<float>(kEmblemAtlasWidth)) << cells[first];
            EXPECT_LE(rect.y + rect.h, static_cast<float>(kEmblemAtlasHeight)) << cells[first];
            for (size_t second = first + 1; second < cells.size(); ++second) {
                EXPECT_NE(cells[first], cells[second]);
                EXPECT_FALSE(Overlap(rect, EmblemRect(cells[second]))) << cells[first] << " and " << cells[second];
            }
        }
    }

    TEST(EmblemSpritesTest, TheCellsFollowTheOrderOfTheScript) {
        // tools/make_emblems.py: cell 0 the person, cells 1..10 the computer of level 1..10, then the turn ring and the calling ring
        EXPECT_EQ(PersonCell(), 0);
        EXPECT_EQ(ComputerCell(ComputerLevel{1}), 1);
        EXPECT_EQ(ComputerCell(ComputerLevel{5}), 5);
        EXPECT_EQ(ComputerCell(ComputerLevel{10}), 10);
        EXPECT_EQ(kTurnRingCell, 11);
        EXPECT_EQ(kCallingRingCell, 12);
        EXPECT_EQ(EmblemRect(kEmblemColumns).x, 0.0f);
        EXPECT_EQ(EmblemRect(kEmblemColumns).y, static_cast<float>(kEmblemCellSize));
        EXPECT_EQ(EmblemRect(1).x, static_cast<float>(kEmblemCellSize));
        EXPECT_EQ(EmblemRect(1).y, 0.0f);
    }

}  // namespace BECore::Mahjong::Tests
